      {/* MODAL ESCOLHER HINO */}
      {isAdding && (
        <div className="fixed inset-0 z-[5000] flex items-center justify-center overflow-hidden">
          <div 
            className="absolute inset-0 bg-black/60 backdrop-blur-2xl animate-fadeIn"
            onClick={() => setIsAdding(false)}
