      {/* MODAL SELETOR DE MÊS */}
      {isMonthPickerOpen && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 backdrop-blur-md flex items-center justify-center z-[3000] p-6 animate-fadeIn">
