import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface WorkerEvent {
  date: string;
  description: string;
}

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, events: WorkerEvent[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: WorkerEvent[], praise: WorkerEvent[], word: WorkerEvent[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));

    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });

    history.forEach(r => {
      const event = { date: r.date, description: r.description };
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(event);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(event);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(event);
    });

    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.date.localeCompare(a.date));
      data[name].praise.sort((a, b) => b.date.localeCompare(a.date));
      data[name].word.sort((a, b) => b.date.localeCompare(a.date));
    });

    return Object.entries(data)
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick, icon }: { label: string, count: number, onClick: () => void, icon: string }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <div className="flex items-center gap-1 mb-2">
        <span className="material-icons text-[10px] text-slate-300 group-hover:text-indigo-400 transition-colors">{icon}</span>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.15em] group-hover:text-indigo-600 transition-colors">{label}</span>
      </div>
      <span className="text-3xl font-black text-[#1a1c3d] leading-none">{count}</span>
      <div className="mt-2 w-5 h-0.5 bg-slate-100 rounded-full group-hover:w-8 group-hover:bg-indigo-400 transition-all"></div>
    </button>
  );

  return (
    <>
      <div className="space-y-8 animate-fadeIn pb-10 max-w-4xl mx-auto">
        <div className="px-2">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Total acumulado de atos realizados</p>
        </div>

        <div className="grid gap-8">
          {stats.map((worker) => (
            <div key={worker.name} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-slate-50 group transition-all">
              <div className="bg-[#1a1c3d] px-8 py-6 flex justify-between items-center relative overflow-hidden">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/5 rounded-full blur-2xl"></div>
                <h3 className="text-white font-black text-xl tracking-tight uppercase relative z-10">{worker.name}</h3>
                <div className="bg-[#ffcc00] text-[#1a1c3d] px-4 py-2 rounded-full font-black text-[10px] shadow-lg flex items-center gap-2 relative z-10">
                  <span className="material-icons text-[14px]">military_tech</span>
                  {worker.total} ATOS TOTAIS
                </div>
              </div>
              <div className="p-5 flex gap-3 bg-slate-50/30">
                <StatBox label="Portão" count={worker.gate.length} icon="door_front" onClick={() => setModalData({ worker: worker.name, role: 'Portão', events: worker.gate })} />
                <StatBox label="Louvor" count={worker.praise.length} icon="music_note" onClick={() => setModalData({ worker: worker.name, role: 'Louvor', events: worker.praise })} />
                <StatBox label="Palavra" count={worker.word.length} icon="record_voice_over" onClick={() => setModalData({ worker: worker.name, role: 'Palavra', events: worker.word })} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Slide-over Drawer para Histórico de Obreiro */}
      {modalData && (
        <div className="fixed inset-0 z-[6000] flex justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setModalData(null)} />
          <div className="relative w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-slideInRight">
            <div className="bg-[#1a1c3d] p-10 relative shrink-0">
              <div className="flex items-center gap-2 mb-1">
                <span className="material-icons text-indigo-400 text-sm">history</span>
                <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block">HISTÓRICO DETALHADO</span>
              </div>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter leading-tight">{modalData.worker}</h3>
              <div className="mt-3 flex gap-2">
                <div className="bg-white/10 px-3 py-1.5 rounded-xl inline-flex items-center gap-2">
                  <span className="text-white font-black text-[10px] uppercase tracking-widest">{modalData.role}</span>
                </div>
                <div className="bg-amber-400 px-3 py-1.5 rounded-xl inline-flex items-center gap-2">
                  <span className="text-[#1a1c3d] font-black text-[10px] uppercase tracking-widest">{modalData.events.length} VEZES</span>
                </div>
              </div>
              <button onClick={() => setModalData(null)} className="absolute top-8 right-8 w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90 transition-transform">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-3">
              {modalData.events.length === 0 ? (
                <div className="py-20 text-center">
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">Nenhum registro encontrado</p>
                </div>
              ) : (
                modalData.events.map((ev, i) => (
                  <div key={i} className="flex justify-between items-center p-5 bg-slate-50 rounded-2xl border border-slate-100 shadow-sm animate-fadeIn" style={{ animationDelay: `${i * 0.05}s` }}>
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center border border-slate-100 shadow-sm">
                        <span className="text-[10px] font-black text-indigo-600">#{modalData.events.length - i}</span>
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-[#1a1c3d] text-base leading-none mb-1">
                          {new Date(ev.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                        </span>
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Culto: {ev.description}</span>
                      </div>
                    </div>
                    <span className="material-icons text-slate-200 text-sm">event_available</span>
                  </div>
                ))
              )}
            </div>

            <div className="p-8 bg-slate-50 shrink-0">
              <button onClick={() => setModalData(null)} className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl uppercase text-[11px] tracking-widest active:scale-95 transition-all shadow-xl">FECHAR DETALHES</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default WorkerRanking;

import React, { useState, useMemo } from 'react';
import { PraiseLearningItem, LearningStatus } from '../types';

interface Props {
  fullSongList: string[];
  learningList: PraiseLearningItem[];
  setLearningList: React.Dispatch<React.SetStateAction<PraiseLearningItem[]>>;
}

const PraiseLearningList: React.FC<Props> = ({ fullSongList, learningList, setLearningList }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<LearningStatus | 'all'>('all');
  const [isAdding, setIsAdding] = useState(false);
  const [addInput, setAddInput] = useState('');

  const stats = useMemo(() => {
    const total = learningList.length;
    const learned = learningList.filter(i => i.status === 'learned').length;
    const learning = learningList.filter(i => i.status === 'learning').length;
    const correcting = learningList.filter(i => i.status === 'correcting').length;
    const notStarted = learningList.filter(i => i.status === 'not_started').length;
    const percent = total > 0 ? Math.round((learned / total) * 100) : 0;
    return { total, learned, learning, correcting, notStarted, percent };
  }, [learningList]);

  const statusWeight: Record<LearningStatus, number> = {
    learning: 1,
    correcting: 2,
    not_started: 3,
    learned: 4
  };

  const filteredItems = useMemo(() => {
    return learningList
      .filter(item => {
        const matchSearch = item.song.toLowerCase().includes(searchTerm.toLowerCase());
        const matchFilter = filter === 'all' || item.status === filter;
        return matchSearch && matchFilter;
      })
      .sort((a, b) => {
        const diff = statusWeight[a.status] - statusWeight[b.status];
        if (diff !== 0) return diff;
        return a.song.localeCompare(b.song);
      });
  }, [learningList, searchTerm, filter]);

  const addSong = (song: string) => {
    if (learningList.some(i => i.song === song)) return;
    const newItem: PraiseLearningItem = {
      song,
      status: 'not_started',
      updatedAt: new Date().toISOString()
    };
    setLearningList(prev => [...prev, newItem]);
    setAddInput('');
    setIsAdding(false);
  };

  const updateStatus = (song: string, status: LearningStatus) => {
    setLearningList(prev => prev.map(i => 
      i.song === song ? { ...i, status, updatedAt: new Date().toISOString() } : i
    ));
  };

  const removeItem = (song: string) => {
    if (window.confirm(`Remover "${song}" do monitoramento?`)) {
      setLearningList(prev => prev.filter(i => i.song !== song));
    }
  };

  const suggestions = useMemo(() => {
    if (addInput.length < 2) return [];
    const lower = addInput.toLowerCase();
    const alreadyInList = new Set(learningList.map(i => i.song));
    return fullSongList
      .filter(s => s.toLowerCase().includes(lower) && !alreadyInList.has(s))
      .slice(0, 15);
  }, [addInput, fullSongList, learningList]);

  const StatusButton = ({ status, active, onClick, count }: { status: LearningStatus | 'all', active: boolean, onClick: () => void, count?: number }) => {
    const labels = { all: 'Todos', learned: 'Sabemos', learning: 'Praticando', correcting: 'Corrigir', not_started: 'Fila' };
    const icons = { all: 'apps', learned: 'verified', learning: 'menu_book', correcting: 'edit_note', not_started: 'schedule' };

    const colors = { 
      all: 'bg-slate-100 text-slate-400 border-slate-200', 
      learned: 'bg-emerald-50 text-emerald-500 border-emerald-100', 
      learning: 'bg-amber-50 text-amber-500 border-amber-100', 
      correcting: 'bg-violet-50 text-violet-500 border-violet-100',
      not_started: 'bg-rose-50 text-rose-400 border-rose-100' 
    };
    const activeColors = { 
      all: 'bg-[#1a1c3d] text-white border-[#1a1c3d]', 
      learned: 'bg-emerald-500 text-white border-emerald-500', 
      learning: 'bg-amber-500 text-white border-amber-500', 
      correcting: 'bg-violet-500 text-white border-violet-500',
      not_started: 'bg-rose-500 text-white border-rose-500' 
    };

    return (
      <button 
        onClick={onClick}
        title={labels[status]}
        className={`relative w-14 h-14 rounded-2xl flex items-center justify-center transition-all shrink-0 border-2 active:scale-90 ${active ? activeColors[status] + ' shadow-lg' : colors[status]}`}
      >
        <span className="material-icons text-2xl">{icons[status]}</span>
        {count !== undefined && count > 0 && (
          <span className={`absolute -top-1.5 -right-1.5 min-w-[20px] h-[20px] px-1 flex items-center justify-center rounded-full text-[9px] font-black border-2 shadow-sm ${active ? 'bg-white text-[#1a1c3d] border-[#1a1c3d]' : 'bg-slate-700 text-white border-white'}`}>
            {count}
          </span>
        )}
      </button>
    );
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fadeIn pb-24 px-1">
      {/* Dashboard Card */}
      <div className="bg-white rounded-[2.5rem] p-6 md:p-10 shadow-xl border border-slate-50">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600">
              <span className="material-icons text-xl">school</span>
            </div>
            <h2 className="text-xl md:text-2xl font-black text-[#1a1c3d] tracking-tight uppercase">Aprendizado</h2>
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="w-11 h-11 md:w-auto md:px-6 md:h-12 bg-[#1a1c3d] text-white rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 active:scale-95 transition-all shadow-lg"
          >
            <span className="material-icons text-xl md:text-sm">add</span>
            <span className="hidden md:inline">Adicionar</span>
          </button>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-6">
          <div className="relative w-28 h-28 shrink-0">
             <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
               <circle className="text-slate-50 stroke-current" strokeWidth="10" fill="transparent" r="40" cx="50" cy="50" />
               <circle className="text-emerald-500 stroke-current" strokeWidth="10" strokeLinecap="round" fill="transparent" r="40" cx="50" cy="50" 
                 style={{ strokeDasharray: '251.2', strokeDashoffset: 251.2 - (251.2 * stats.percent) / 100, transition: 'stroke-dashoffset 1s ease' }} 
               />
             </svg>
             <div className="absolute inset-0 flex flex-col items-center justify-center">
               <span className="text-xl font-black text-[#1a1c3d]">{stats.percent}%</span>
               <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest">OK</span>
             </div>
          </div>

          <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-2.5 w-full">
             <div className="bg-amber-50/50 p-3 rounded-2xl text-center border border-amber-100">
               <div className="text-lg font-black text-amber-600 leading-none">{stats.learning}</div>
               <div className="text-[8px] font-black text-amber-500 uppercase tracking-tighter mt-1">Praticando</div>
             </div>
             <div className="bg-violet-50/50 p-3 rounded-2xl text-center border border-violet-100">
               <div className="text-lg font-black text-violet-600 leading-none">{stats.correcting}</div>
               <div className="text-[8px] font-black text-violet-500 uppercase tracking-tighter mt-1">Corrigir</div>
             </div>
             <div className="bg-rose-50/50 p-3 rounded-2xl text-center border border-rose-100">
               <div className="text-lg font-black text-rose-600 leading-none">{stats.notStarted}</div>
               <div className="text-[8px] font-black text-rose-500 uppercase tracking-tighter mt-1">Fila</div>
             </div>
             <div className="bg-emerald-50/50 p-3 rounded-2xl text-center border border-emerald-100">
               <div className="text-lg font-black text-emerald-600 leading-none">{stats.learned}</div>
               <div className="text-[8px] font-black text-emerald-500 uppercase tracking-tighter mt-1">Sabemos</div>
             </div>
          </div>
        </div>
      </div>

      <div className="space-y-4 px-1">
        <div className="relative">
          <span className="material-icons absolute left-4 top-1/2 -translate-y-1/2 text-slate-300">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar hino..." 
            className="w-full bg-white border border-slate-100 rounded-2xl pl-12 pr-4 py-4 font-bold text-sm text-slate-600 shadow-sm outline-none focus:ring-4 focus:ring-indigo-50 transition-all"
          />
        </div>

        <div className="flex justify-center md:justify-start gap-4 pb-2 px-1">
          <StatusButton status="all" active={filter === 'all'} onClick={() => setFilter('all')} count={stats.total} />
          <StatusButton status="learning" active={filter === 'learning'} onClick={() => setFilter('learning'} count={stats.learning} />
          <StatusButton status="correcting" active={filter === 'correcting'} onClick={() => setFilter('correcting'} count={stats.correcting} />
          <StatusButton status="not_started" active={filter === 'not_started'} onClick={() => setFilter('not_started'} count={stats.notStarted} />
          <StatusButton status="learned" active={filter === 'learned'} onClick={() => setFilter('learned'} count={stats.learned} />
        </div>
      </div>

      <div className="space-y-3 px-1">
        {filteredItems.length === 0 ? (
          <div className="text-center py-16 bg-white/50 rounded-[2.5rem] border-2 border-dashed border-slate-200">
            <span className="material-icons text-slate-200 text-5xl mb-3">library_music</span>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">Nenhum hino encontrado</p>
          </div>
        ) : (
          filteredItems.map(item => (
            <div key={item.song} className="bg-white rounded-[2rem] overflow-hidden shadow-sm border border-slate-100 flex flex-col animate-fadeIn">
              <div className="flex flex-1">
                <div className={`w-1.5 shrink-0 ${item.status === 'learned' ? 'bg-emerald-500' : item.status === 'learning' ? 'bg-amber-400' : item.status === 'correcting' ? 'bg-violet-500' : 'bg-rose-400'}`}></div>
                <div className="p-5 flex-1 flex flex-col gap-4">
                  <div className="flex justify-between items-start gap-3">
                    <div className="flex-1 min-w-0">
                      <h4 className="text-[#1a1c3d] font-black text-sm leading-snug break-words uppercase tracking-tight">{item.song}</h4>
                      <div className="flex items-center gap-1.5 mt-1">
                        <span className="material-icons text-[10px] text-slate-300">update</span>
                        <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">
                          {new Date(item.updatedAt).toLocaleDateString('pt-BR')}
                        </span>
                      </div>
                    </div>
                    <button onClick={() => removeItem(item.song)} className="w-10 h-10 -mr-2 -mt-2 flex items-center justify-center text-slate-200 hover:text-rose-500 transition-colors">
                      <span className="material-icons text-lg">delete_outline</span>
                    </button>
                  </div>
                  <div className="flex items-center gap-1.5 bg-slate-50 p-1.5 rounded-[1.25rem]">
                    <button onClick={() => updateStatus(item.song, 'not_started')} className={`flex-1 h-11 rounded-xl flex items-center justify-center transition-all ${item.status === 'not_started' ? 'bg-rose-500 text-white shadow-md' : 'text-slate-300'}`} title="Fila"><span className="material-icons text-xl">schedule</span></button>
                    <button onClick={() => updateStatus(item.song, 'learning')} className={`flex-1 h-11 rounded-xl flex items-center justify-center transition-all ${item.status === 'learning' ? 'bg-amber-500 text-white shadow-md' : 'text-slate-300'}`} title="Praticando"><span className="material-icons text-xl">menu_book</span></button>
                    <button onClick={() => updateStatus(item.song, 'correcting')} className={`flex-1 h-11 rounded-xl flex items-center justify-center transition-all ${item.status === 'correcting' ? 'bg-violet-500 text-white shadow-md' : 'text-slate-300'}`} title="Corrigir"><span className="material-icons text-xl">edit_note</span></button>
                    <button onClick={() => updateStatus(item.song, 'learned')} className={`flex-1 h-11 rounded-xl flex items-center justify-center transition-all ${item.status === 'learned' ? 'bg-emerald-500 text-white shadow-md' : 'text-slate-300'}`} title="Aprendido"><span className="material-icons text-xl">verified</span></button>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Slide-up para Escolher Hino */}
      {isAdding && (
        <div className="fixed inset-0 z-[6000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setIsAdding(false)} />
          <div className="relative bg-white rounded-t-[3.5rem] shadow-2xl flex flex-col h-[90vh] animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mt-6 shrink-0"></div>

            <div className="p-8 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-3">
                <span className="material-icons text-indigo-600">library_add</span>
                <h3 className="text-[#1a1c3d] font-black text-xl uppercase tracking-tighter">Escolher Hino</h3>
              </div>
              <button 
                onClick={() => setIsAdding(false)} 
                className="w-10 h-10 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 active:scale-90"
              >
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            <div className="px-8 pb-4 shrink-0">
              <div className="relative">
                <span className="material-icons absolute left-4 top-1/2 -translate-y-1/2 text-slate-300">search</span>
                <input 
                  autoFocus
                  type="text" 
                  value={addInput} 
                  onChange={e => setAddInput(e.target.value)} 
                  placeholder="Número ou nome do hino..." 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-12 py-5 font-bold text-sm text-[#1a1c3d] outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all"
                />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto space-y-2 p-8 pt-2 custom-scrollbar">
              {suggestions.length === 0 ? (
                <div className="text-center py-20 opacity-20">
                  <span className="material-icons text-7xl">search</span>
                  <p className="text-[10px] font-black uppercase tracking-widest mt-4">Digite para buscar hinos</p>
                </div>
              ) : (
                suggestions.map((s, i) => (
                  <button 
                    key={s} 
                    onClick={() => addSong(s)}
                    className="w-full p-5 bg-slate-50/50 hover:bg-indigo-50 active:scale-[0.98] rounded-[1.5rem] text-left font-bold text-xs text-slate-700 flex justify-between items-center transition-all border border-transparent hover:border-indigo-100 animate-fadeIn"
                    style={{ animationDelay: `${i * 0.03}s` }}
                  >
                    <span className="truncate pr-4 uppercase tracking-tight">{s}</span>
                    <span className="material-icons text-indigo-300">add_circle_outline</span>
                  </button>
                ))
              )}
            </div>

            <div className="p-8 bg-white shrink-0">
              <button 
                onClick={() => setIsAdding(false)}
                className="w-full py-5 bg-slate-50 text-slate-400 font-black rounded-3xl uppercase text-[11px] tracking-widest"
              >
                CANCELAR
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PraiseLearningList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <>
      {/* Modal de Sucesso - Restaurado conforme versão anterior */}
      {showSuccessModal && (
        <div className="fixed inset-0 z-[7000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-md animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3.5rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-white">
            <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-500">
              <span className="material-icons text-4xl">check_circle</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mb-8">Dados registrados com sucesso.</p>
            <button 
              onClick={() => setShowSuccessModal(false)} 
              className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl shadow-lg active:scale-95 transition-all uppercase text-xs tracking-widest"
            >
              OK, CONTINUAR
            </button>
          </div>
        </div>
      )}

      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
        <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
          <div className="space-y-8">
            {/* DATA E PERÍODO */}
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col items-center">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input 
                    type="date" 
                    value={draft.date} 
                    onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                    className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                  />
                </FormInput>
                <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                  <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            {/* LOUVORES */}
            <div className="space-y-4 pt-6 border-t border-slate-50">
              <Label>Hinos</Label>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={inputValue} 
                  onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                  placeholder="Hino ou Nº..." 
                />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                      <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                  {draft.songs.length > 0 && (
                    <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                      <span className="material-icons text-xs">share</span> COMPARTILHAR
                    </button>
                  )}
                </div>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                  {draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* ESCALA */}
            <div className="space-y-5 pt-6 border-t border-slate-50">
              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select 
                    value={draft.roles.gate} 
                    onChange={e => updateRole('gate', e.target.value)} 
                    className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                  >
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {dateInfo.isWednesday && (
                <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700">
                  <span className="text-lg">🌸</span>
                  <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto do Grupo de Senhoras</span>
                </div>
              )}

              {!dateInfo.isWednesday && (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <Label>Louvor</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col min-h-[70px] justify-end">
                    {draft.roles.word === 'TRANSMISSÃO' ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-fadeIn">
                        <span className="text-lg">📡</span>
                        <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Transmissão via satélite</span>
                      </div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>

            <button 
              onClick={handleSave} 
              disabled={draft.songs.length === 0} 
              className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
            >
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'FINALIZAR'}
            </button>

            {editingId && (
              <button 
                onClick={onCancelEdit}
                className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors"
              >
                CANCELAR
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Bottom Sheet para Hino Recorrente (Continua como Bottom Sheet por ser seletor) */}
      {pendingSong && (
        <div className="fixed inset-0 z-[6000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setPendingSong(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-[0_-20px_50px_rgba(0,0,0,0.1)] animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mb-6 text-amber-500">
                <span className="material-icons text-3xl">warning_amber</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
              <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Cantado há apenas <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Deseja prosseguir?</p>

              <div className="w-full flex flex-col gap-3">
                <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95">CONFIRMAR E ADICIONAR</button>
                <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

const CACHE_NAME = 'icm-gestao-v7';
const PRECACHE_ASSETS = [
  '/',
  '/index.html',
  '/index.tsx',
  '/manifest.json',
  '/types.ts',
  '/constants.ts',
  '/praiseList.ts',
  '/db.ts',
  '/App.tsx',
  'https://cdn-icons-png.flaticon.com/512/1672/1672225.png',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/icon?family=Material+Icons',
  'https://fonts.gstatic.com/s/materialicons/v142/flUhRq6tzZclQEJ-Vdg-IuiaDsNcIhQ8tQ.woff2',
  'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800;900&display=swap'
];

const ESM_DEPS = [
  'https://esm.sh/react@^19.2.3',
  'https://esm.sh/react-dom@^19.2.3',
  'https://esm.sh/react@^19.2.3/',
  'https://esm.sh/react-dom@^19.2.3/'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return Promise.allSettled(
        [...PRECACHE_ASSETS, ...ESM_DEPS].map(url => 
          cache.add(url).catch(err => console.warn(`Falha no cache: ${url}`))
        )
      );
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (url.host === 'esm.sh' || url.host.includes('fonts.') || url.host.includes('cdn.tailwindcss.com') || url.host.includes('flaticon.com')) {
    event.respondWith(
      caches.match(request).then((cachedResponse) => {
        if (cachedResponse) return cachedResponse;
        return fetch(request).then((networkResponse) => {
          if (networkResponse.status === 200) {
            const cacheCopy = networkResponse.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, cacheCopy));
          }
          return networkResponse;
        }).catch(() => new Response("Offline", { status: 503 }));
      })
    );
    return;
  }

  event.respondWith(
    fetch(request)
      .then((networkResponse) => {
        if (request.method === 'GET' && networkResponse.status === 200) {
          const cacheCopy = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, cacheCopy));
        }
        return networkResponse;
      })
      .catch(() => {
        return caches.match(request).then((cachedResponse) => {
          if (cachedResponse) return cachedResponse;
          if (request.mode === 'navigate') return caches.match('/index.html') || caches.match('/');
          return new Response("Offline", { status: 503 });
        });
      })
  );
});

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <>
      {/* Modal de Sucesso - CENTRALIZADO (Versão que você gosta) */}
      {showSuccessModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-md animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3.5rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-white">
            <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-500">
              <span className="material-icons text-4xl">check_circle</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mb-8">Dados registrados com sucesso.</p>
            <button 
              onClick={() => setShowSuccessModal(false)} 
              className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl shadow-lg active:scale-95 transition-all uppercase text-xs tracking-widest"
            >
              OK, CONTINUAR
            </button>
          </div>
        </div>
      )}

      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
        <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
          <div className="space-y-8">
            {/* DATA E PERÍODO */}
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col items-center">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input 
                    type="date" 
                    value={draft.date} 
                    onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                    className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                  />
                </FormInput>
                <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                  <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            {/* LOUVORES */}
            <div className="space-y-4 pt-6 border-t border-slate-50">
              <Label>Hinos</Label>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={inputValue} 
                  onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                  placeholder="Hino ou Nº..." 
                />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                      <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                  {draft.songs.length > 0 && (
                    <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                      <span className="material-icons text-xs">share</span> COMPARTILHAR
                    </button>
                  )}
                </div>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                  {draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'opacity-50' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* ESCALA */}
            <div className="space-y-5 pt-6 border-t border-slate-50">
              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select 
                    value={draft.roles.gate} 
                    onChange={e => updateRole('gate', e.target.value)} 
                    className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                  >
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {dateInfo.isWednesday && (
                <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700">
                  <span className="text-lg">🌸</span>
                  <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto do Grupo de Senhoras</span>
                </div>
              )}

              {!dateInfo.isWednesday && (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <Label>Louvor</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col min-h-[70px] justify-end">
                    {draft.roles.word === 'TRANSMISSÃO' ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-fadeIn">
                        <span className="text-lg">📡</span>
                        <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Transmissão via satélite</span>
                      </div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>

            <button 
              onClick={handleSave} 
              disabled={draft.songs.length === 0} 
              className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
            >
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'FINALIZAR'}
            </button>

            {editingId && (
              <button 
                onClick={onCancelEdit}
                className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors"
              >
                CANCELAR
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Bottom Sheet para Hino Recorrente */}
      {pendingSong && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setPendingSong(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mb-6 text-amber-500">
                <span className="material-icons text-3xl">warning_amber</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
              <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Cantado há apenas <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Deseja prosseguir?</p>

              <div className="w-full flex flex-col gap-3">
                <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95">CONFIRMAR E ADICIONAR</button>
                <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isMonthPickerOpen, setIsMonthPickerOpen] = useState(false);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.roles?.praise?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.roles?.gate?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => {
      const dateCompare = b.date.localeCompare(a.date);
      if (dateCompare !== 0) return dateCompare;
      if (a.description === 'EBD' && b.description === 'DOM') return 1;
      if (a.description === 'DOM' && b.description === 'EBD') return -1;
      return 0;
    });

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const formatServiceMessage = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    const isSatellite = r.roles.word === 'TRANSMISSÃO';

    let msg = `*RELATÓRIO DE CULTO - ${dateFormatted}* (${r.description})\n`;
    msg += `> Portão: ${r.roles.gate || '-'}\n`;

    if (day !== 3) {
      msg += `> Louvor: ${r.roles.praise || '-'}\n`;
      if (day !== 1) msg += `> Palavra: ${r.roles.word || '-'}\n`;
      if (!isSatellite && r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
      else if (isSatellite) msg += `*Satélite: Transmissão*\n`;
    } else {
      msg += `*Culto das Senhoras*\n`;
    }

    if (r.songs.length > 0) {
      msg += `\n*LOUVORES:* \n`;
      r.songs.forEach((s, i) => msg += ` ${i + 1}. ${s}\n`);
    }

    return msg;
  };

  const sortChronologically = (records: ServiceRecord[]) => {
    return [...records].sort((a, b) => {
      const dateCompare = a.date.localeCompare(b.date);
      if (dateCompare !== 0) return dateCompare;
      if (a.description === 'EBD' && b.description === 'DOM') return -1;
      if (a.description === 'DOM' && b.description === 'EBD') return 1;
      return 0;
    });
  };

  const shareIndividual = (record: ServiceRecord) => {
    let msg = `*ICM SANTO ANTÔNIO II*\n\n`;
    msg += formatServiceMessage(record);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const rawRecords = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    if (!rawRecords) return;
    const sortedRecords = sortChronologically(rawRecords);

    let msg = `*RESUMO MENSAL - ${monthKey}*\n*ICM SANTO ANTÔNIO II*\n\n`;
    sortedRecords.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `_ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareAll = () => {
    const sortedHistory = sortChronologically(history);
    let msg = `*HISTÓRICO COMPLETO DE CULTOS*\n*ICM SANTO ANTÔNIO II*\n\n`;
    const limitedHistory = sortedHistory.slice(-15);

    limitedHistory.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `_ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const InfoTag = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
    if (!value) return null;
    return (
      <div className="flex flex-col border-l-2 border-indigo-100 pl-3">
        <div className="flex items-center gap-1 mb-0.5">
          <span className="material-icons text-[10px] text-slate-300">{icon}</span>
          <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest">{label}</span>
        </div>
        <span className="text-[11px] font-black text-[#1a1c3d] truncate">{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10">
      <div className="flex items-center gap-2 px-1">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" />
        </div>
        <button onClick={() => setIsMonthPickerOpen(true)} title="Compartilhar por Mês" className="bg-indigo-500 text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-transform">
           <span className="material-icons">calendar_month</span>
        </button>
        <button onClick={shareAll} title="Compartilhar Geral" className="bg-[#1a1c3d] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-transform">
           <span className="material-icons">share</span>
        </button>
      </div>

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-4">
          <div className="px-4">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">{month}</h3>
          </div>

          <div className="grid gap-4">
            {records.map(record => (
              <div key={record.id} className="bg-white rounded-[2.5rem] p-6 md:p-8 shadow-sm border border-slate-100 animate-fadeIn">
                <div className="flex flex-col gap-6">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                        <span className="text-[10px] font-black text-indigo-600 leading-none">{new Date(record.date + 'T12:00:00').getDate()}</span>
                        <span className="text-[8px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[new Date(record.date + 'T12:00:00').getDay()]}</span>
