import { AppData } from './types';
import { STORAGE_KEY } from './constants';
import { db, doc, setDoc, getDoc, auth } from './firebase';

const DB_NAME = 'ChurchServiceDB';
const DB_VERSION = 1;
const STORE_NAME = 'reports';

export const initDB = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };

    request.onsuccess = () => {
      if (navigator.storage && navigator.storage.persist) {
        navigator.storage.persist().then(persistent => {
          console.log(persistent ? "Armazenamento persistente ativado" : "Armazenamento persistente negado");
        });
      }
      resolve();
    };

    request.onerror = () => reject(request.error);
  });
};

export const saveData = async (data: AppData): Promise<void> => {
  // Salva Localmente (Prioridade)
  const saveLocal = new Promise<void>((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onsuccess = () => {
      const db = request.result;
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      store.put(data, STORAGE_KEY);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    };
  });

  await saveLocal;

  // Sincroniza com Firebase se logado e online
  if (auth.currentUser && navigator.onLine) {
    try {
      const userDoc = doc(db, "users", auth.currentUser.uid);
      await setDoc(userDoc, {
        ...data,
        lastSync: new Date().toISOString()
      }, { merge: true });
      console.log("Sincronizado com a nuvem.");
    } catch (e) {
      console.warn("Falha na sincronização cloud:", e);
    }
  }
};

export const loadData = (): Promise<AppData | null> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onsuccess = () => {
      const db = request.result;
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const getRequest = store.get(STORAGE_KEY);
      getRequest.onsuccess = () => resolve(getRequest.result || null);
      getRequest.onerror = () => reject(getRequest.error);
    };
    request.onerror = () => reject(request.error);
  });
};

export const loadFromCloud = async (): Promise<AppData | null> => {
  if (!auth.currentUser) return null;
  try {
    const userDoc = doc(db, "users", auth.currentUser.uid);
    const snap = await getDoc(userDoc);
    if (snap.exists()) {
      return snap.data() as AppData;
    }
  } catch (e) {
    console.error("Erro ao carregar da nuvem:", e);
  }
  return null;
};

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft, PraiseLearningItem } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import PraiseLearningList from './components/PraiseLearningList';
import { initDB, saveData, loadData } from './db';
import { auth, onAuthStateChanged } from './firebase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'learning' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [learningList, setLearningList] = useState<PraiseLearningItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [user, setUser] = useState(auth.currentUser);
  const [historyFilter, setHistoryFilter] = useState<{ worker: string; role: string } | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => {
      setUser(u);
    });

    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.learningList) setLearningList(data.learningList);
          if (data.draft) {
            setDraft({ 
              ...data.draft, 
              date: getTodayDate(), 
              roles: data.draft.roles || { ...emptyRoles }
            });
          }
        }
      } catch (e) {
        console.error("Erro no DB", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();
    return () => {
      unsubscribe();
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) saveData({ history, customSongs, draft, learningList });
  }, [history, customSongs, draft, learningList, isLoading]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ 
      date: getTodayDate(), 
      description: '', 
      songs: [], 
      roles: { ...emptyRoles }
    });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => (
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center p-2.5">
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
      </div>
      <div className="flex flex-col">
        <div className="flex items-center gap-2">
           <div className="w-2 h-2 bg-amber-400 rounded-full animate-pulse"></div>
           <span className="text-white/60 font-black text-[10px] tracking-[0.2em] uppercase">Gestão de Culto</span>
        </div>
        <h1 className="text-white font-black text-xl tracking-tighter leading-tight uppercase whitespace-nowrap">Santo Antônio II</h1>
        <div className="mt-1 bg-white/10 self-start px-3 py-1 rounded-full flex items-center gap-2">
           <span className="material-icons text-amber-400 text-xs">analytics</span>
           <span className="text-white font-black text-[10px] uppercase">{history.length} Cultos</span>
        </div>
      </div>
    </div>
  );

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex flex-col items-center justify-center text-white p-10"><img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-20 h-20 animate-bounce mb-6" /><p className="font-black tracking-widest text-sm animate-pulse">CARREGANDO SISTEMA...</p></div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      <aside className="hidden md:flex w-96 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-12 border-b border-white/5">
          <AppBrand />
        </div>
        <nav className="flex-1 py-10 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`w-full flex items-center gap-6 px-12 py-6 transition-all duration-300 ${activeTab === item.id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="text-sm uppercase font-black tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      </aside>

      <header className="md:hidden bg-[#1a1c3d] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl rounded-b-[2rem]">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="p-4 bg-white/10 rounded-2xl active:scale-90 transition-transform">
          <span className="material-icons text-3xl">menu</span>
        </button>
      </header>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-lg" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1a1c3d] shadow-2xl flex flex-col animate-fadeIn border-l border-white/5">
            <div className="p-10 flex justify-between items-center border-b border-white/5">
              <span className="text-white/40 font-black text-xs tracking-widest uppercase">Navegação Principal</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center text-white/40"><span className="material-icons">close</span></button>
            </div>
            <nav className="flex-1 py-6 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={`w-full flex items-center gap-8 px-10 py-7 border-b border-white/5 ${activeTab === item.id ? 'text-amber-400 bg-white/5 font-black' : 'text-white/60'}`}
                >
                  <span className="material-icons text-3xl">{item.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-[92px] md:top-0 z-[190] shadow-lg">Você está operando offline.</div>}

        <div className="px-4 pt-14 pb-20 md:p-16 animate-fadeIn max-w-6xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}

          {activeTab === 'history' && (
            <HistoryList 
              history={history} 
              onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} 
              onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} 
              onClearAll={() => {}} 
              externalFilter={historyFilter}
              onClearExternalFilter={() => setHistoryFilter(null)}
            />
          )}

          {activeTab === 'learning' && <PraiseLearningList fullSongList={fullSongList} learningList={learningList} setLearningList={setLearningList} />}

          {activeTab === 'workers' && (
            <WorkerRanking 
              history={history} 
              onFilterHistory={(worker, role) => {
                setHistoryFilter({ worker, role });
                setActiveTab('history');
              }}
            />
          )}

          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} learningList={learningList} onRestore={(h, c, l) => { setHistory(h); setCustomSongs(c); setLearningList(l || []); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { ServiceRecord, PraiseLearningItem } from '../types';
import { auth, googleProvider, signInWithPopup, signOut, onAuthStateChanged } from '../firebase';
import { loadFromCloud, saveData } from '../db';

interface Props {
  history: ServiceRecord[];
  customSongs: string[];
  learningList: PraiseLearningItem[];
  onRestore: (history: ServiceRecord[], customSongs: string[], learningList: PraiseLearningItem[]) => void;
}

const BackupRestore: React.FC<Props> = ({ history, customSongs, learningList, onRestore }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [user, setUser] = useState(auth.currentUser);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => setUser(u));
    return () => unsubscribe();
  }, []);

  const handleBackup = () => {
    if (history.length === 0 && customSongs.length === 0 && learningList.length === 0) {
      alert("Não há dados para exportar.");
      return;
    }
    const dataStr = JSON.stringify({ history, customSongs, learningList }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_igreja_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && Array.isArray(json.history)) {
          if (window.confirm("Isso substituirá seus dados atuais. Continuar?")) {
            onRestore(json.history, json.customSongs || [], json.learningList || []);
          }
        } else {
          alert("Arquivo inválido.");
        }
      } catch (err) {
        alert("Erro ao ler o arquivo.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleLogin = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (e) {
      console.error(e);
      alert("Erro ao fazer login com Google.");
    }
  };

  const handleRestoreFromCloud = async () => {
    if (!window.confirm("Isso substituirá seus dados locais pela versão salva na nuvem. Continuar?")) return;
    setIsSyncing(true);
    try {
      const data = await loadFromCloud();
      if (data) {
        onRestore(data.history, data.customSongs || [], data.learningList || []);
        alert("Dados restaurados da nuvem com sucesso!");
      } else {
        alert("Nenhum dado encontrado na sua conta cloud.");
      }
    } catch (e) {
      alert("Erro ao carregar dados da nuvem.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSyncNow = async () => {
    setIsSyncing(true);
    try {
      await saveData({ history, customSongs, learningList });
      alert("Dados enviados para a nuvem!");
    } catch (e) {
      alert("Erro na sincronização manual.");
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800 flex items-center gap-3">
          <span className="material-icons text-indigo-600">settings</span>
          Backup e Sincronização
        </h2>
      </div>

      {/* Cloud Sync Panel */}
      <div className="bg-[#1a1c3d] rounded-[2.5rem] p-8 md:p-10 shadow-2xl border border-white/5 relative overflow-hidden">
        <div className="absolute -right-10 -bottom-10 opacity-5">
           <span className="material-icons text-[15rem]">cloud_sync</span>
        </div>

        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
          <div className="flex items-center gap-6">
            <div className={`w-16 h-16 rounded-3xl flex items-center justify-center shadow-xl ${user ? 'bg-emerald-500 text-white' : 'bg-white/10 text-white/40'}`}>
              <span className="material-icons text-3xl">{user ? 'cloud_done' : 'cloud_off'}</span>
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] mb-1">Nuvem Firebase</span>
              <h3 className="text-white font-black text-lg tracking-tight">
                {user ? `Conectado: ${user.displayName}` : 'Sincronização Desativada'}
              </h3>
              <p className="text-white/40 text-[10px] font-medium uppercase mt-1">
                {user ? 'Seus dados estão sendo salvos em tempo real' : 'Faça login para salvar seus dados na nuvem'}
              </p>
            </div>
          </div>

          <div className="flex gap-3">
            {user ? (
              <>
                <button 
                  disabled={isSyncing}
                  onClick={handleSyncNow}
                  className="bg-white/10 hover:bg-white/20 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-2"
                >
                  <span className={`material-icons text-sm ${isSyncing ? 'animate-spin' : ''}`}>{isSyncing ? 'sync' : 'upload'}</span>
                  {isSyncing ? 'Sincronizando...' : 'Enviar Agora'}
                </button>
                <button 
                  onClick={handleRestoreFromCloud}
                  className="bg-amber-400 text-[#1a1c3d] px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95"
                >
                  Restaurar Cloud
                </button>
                <button 
                  onClick={() => signOut(auth)}
                  className="bg-rose-500/20 text-rose-300 hover:bg-rose-500/30 px-4 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all"
                >
                  Sair
                </button>
              </>
            ) : (
              <button 
                onClick={handleLogin}
                className="bg-white text-[#1a1c3d] px-8 py-4 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center gap-3 shadow-xl active:scale-95 transition-all"
              >
                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/instrumentation/google.svg" className="w-5 h-5" alt="G" />
                Entrar com Google
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Local Backup Options */}
        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-indigo-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-indigo-600">
            <span className="material-icons text-3xl">download</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase tracking-tight">Exportar Offline</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed px-4">Baixe um arquivo .json para backup manual ou transferência sem internet.</p>
          <button 
            onClick={handleBackup} 
            className="w-full py-5 bg-indigo-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase"
          >
            BAIXAR ARQUIVO
          </button>
        </div>

        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-emerald-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-emerald-600">
            <span className="material-icons text-3xl">file_open</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase tracking-tight">Importar Arquivo</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed px-4">Restaure relatórios a partir de um backup local baixado anteriormente.</p>
          <button 
            onClick={() => fileInputRef.current?.click()} 
            className="w-full py-5 bg-emerald-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase"
          >
            ABRIR BACKUP
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>

      <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
        <h4 className="text-[10px] font-black text-slate-400 uppercase mb-4 tracking-widest px-1">Resumo do Sistema</h4>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-50 flex flex-col">
            <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest mb-1">Total de Cultos</span>
            <span className="text-xl font-black text-[#1a1c3d]">{history.length}</span>
          </div>
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-50 flex flex-col">
            <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest mb-1">Banco Local</span>
            <span className="text-xl font-black text-emerald-500 flex items-center gap-2">
              <span className="material-icons text-sm">storage</span> Ativo
            </span>
          </div>
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-50 flex flex-col">
            <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest mb-1">Status Offline</span>
            <span className={`text-xl font-black ${!navigator.onLine ? 'text-amber-500' : 'text-indigo-400'}`}>
              {navigator.onLine ? 'Conectado' : 'Modo Offline'}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BackupRestore;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface WorkerEvent {
  date: string;
  description: string;
}

// Fixed: Added onFilterHistory to Props interface to resolve TypeScript error in App.tsx
interface Props {
  history: ServiceRecord[];
  onFilterHistory: (worker: string, role: string) => void;
}

const WorkerRanking: React.FC<Props> = ({ history, onFilterHistory }) => {
  // Fixed: Added roleId to modalData to facilitate filtering by internal role key
  const [modalData, setModalData] = useState<{ worker: string, role: string, roleId: string, events: WorkerEvent[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: WorkerEvent[], praise: WorkerEvent[], word: WorkerEvent[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));

    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });

    history.forEach(r => {
      const event = { date: r.date, description: r.description };
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(event);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(event);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(event);
    });

    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.date.localeCompare(a.date));
      data[name].praise.sort((a, b) => b.date.localeCompare(a.date));
      data[name].word.sort((a, b) => b.date.localeCompare(a.date));
    });

    return Object.entries(data)
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick, icon }: { label: string, count: number, onClick: () => void, icon: string }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <div className="flex items-center gap-1 mb-2">
        <span className="material-icons text-[10px] text-slate-300 group-hover:text-indigo-400 transition-colors">{icon}</span>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.15em] group-hover:text-indigo-600 transition-colors">{label}</span>
      </div>
      <span className="text-3xl font-black text-[#1a1c3d] leading-none">{count}</span>
      <div className="mt-2 w-5 h-0.5 bg-slate-100 rounded-full group-hover:w-8 group-hover:bg-indigo-400 transition-all"></div>
    </button>
  );

  return (
    <>
      <div className="space-y-8 animate-fadeIn pb-10 max-w-4xl mx-auto">
        <div className="px-2 pt-2 md:pt-0">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Total acumulado de atos realizados</p>
        </div>

        <div className="grid gap-8">
          {stats.map((worker) => (
            <div key={worker.name} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-slate-50 group transition-all">
              <div className="bg-[#1a1c3d] px-8 py-6 flex justify-between items-center relative overflow-hidden">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/5 rounded-full blur-2xl"></div>
                <h3 className="text-white font-black text-xl tracking-tight uppercase relative z-10">{worker.name}</h3>
                <div className="bg-[#ffcc00] text-[#1a1c3d] px-4 py-2 rounded-full font-black text-[10px] shadow-lg flex items-center gap-2 relative z-10">
                  <span className="material-icons text-[14px]">military_tech</span>
                  {worker.total} ATOS TOTAIS
                </div>
              </div>
              <div className="p-5 flex gap-3 bg-slate-50/30">
                <StatBox label="Portão" count={worker.gate.length} icon="door_front" onClick={() => setModalData({ worker: worker.name, role: 'Portão', roleId: 'gate', events: worker.gate })} />
                <StatBox label="Louvor" count={worker.praise.length} icon="music_note" onClick={() => setModalData({ worker: worker.name, role: 'Louvor', roleId: 'praise', events: worker.praise })} />
                <StatBox label="Palavra" count={worker.word.length} icon="record_voice_over" onClick={() => setModalData({ worker: worker.name, role: 'Palavra', roleId: 'word', events: worker.word })} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Slide-over Drawer para Histórico de Obreiro - Ajustado para mobile */}
      {modalData && (
        <div className="fixed inset-0 z-[6000] flex justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setModalData(null)} />
          <div className="relative w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-slideInRight">
            {/* Cabeçalho do Drawer com padding extra no mobile (pt-24) */}
            <div className="bg-[#1a1c3d] pt-24 pb-10 px-10 md:pt-12 md:pb-12 md:px-10 relative shrink-0">
              <div className="flex items-center gap-2 mb-1">
                <span className="material-icons text-indigo-400 text-sm">history</span>
                <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block">HISTÓRICO DETALHADO</span>
              </div>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter leading-tight">{modalData.worker}</h3>

              {/* Opção e quantidade - Movidos mais para baixo */}
              <div className="mt-4 flex flex-wrap gap-2">
                <div className="bg-white/10 px-3 py-1.5 rounded-xl inline-flex items-center gap-2 border border-white/5">
                  <span className="text-white/80 font-black text-[10px] uppercase tracking-widest">{modalData.role}</span>
                </div>
                <div className="bg-amber-400 px-3 py-1.5 rounded-xl inline-flex items-center gap-2 shadow-lg">
                  <span className="text-[#1a1c3d] font-black text-[10px] uppercase tracking-widest">{modalData.events.length} VEZES</span>
                </div>
              </div>

              {/* Botão fechar ajustado para não conflitar com menu superior */}
              <button 
                onClick={() => setModalData(null)} 
                className="absolute top-20 md:top-8 right-8 w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90 transition-transform hover:bg-white/20"
              >
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-3">
              {modalData.events.length === 0 ? (
                <div className="py-20 text-center">
                  <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">Nenhum registro encontrado</p>
                </div>
              ) : (
                modalData.events.map((ev, i) => (
                  <div key={i} className="flex justify-between items-center p-5 bg-slate-50 rounded-2xl border border-slate-100 shadow-sm animate-fadeIn" style={{ animationDelay: `${i * 0.05}s` }}>
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center border border-slate-100 shadow-sm">
                        <span className="text-[10px] font-black text-indigo-600">#{modalData.events.length - i}</span>
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-[#1a1c3d] text-base leading-none mb-1">
                          {new Date(ev.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                        </span>
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Culto: {ev.description}</span>
                      </div>
                    </div>
                    <span className="material-icons text-slate-200 text-sm">event_available</span>
                  </div>
                ))
              )}
            </div>

            <div className="p-8 bg-slate-50 shrink-0 border-t border-slate-100 flex flex-col gap-3">
              <button 
                onClick={() => {
                  if (modalData) {
                    onFilterHistory(modalData.worker, modalData.roleId);
                    setModalData(null);
                  }
                }}
                className="w-full py-5 bg-amber-400 text-[#1a1c3d] font-black rounded-3xl uppercase text-[11px] tracking-widest active:scale-95 transition-all shadow-xl"
              >
                VER NO HISTÓRICO
              </button>
              <button onClick={() => setModalData(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">VOLTAR AO RANKING</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default WorkerRanking;

