import React, { useRef, useState, useEffect } from 'react';
import { ServiceRecord, PraiseLearningItem } from '../types';
import { supabase } from '../supabase';

interface Props {
  history: ServiceRecord[];
  customSongs: string[];
  learningList: PraiseLearningItem[];
  onRestore: (history: ServiceRecord[], customSongs: string[], learningList: PraiseLearningItem[]) => void;
}

const BackupRestore: React.FC<Props> = ({ history, customSongs, learningList, onRestore }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncDate, setLastSyncDate] = useState<string | null>(null);

  const fetchLastSync = async (userId: string) => {
    try {
      const { data } = await supabase
        .from('user_data')
        .select('updated_at')
        .eq('user_id', userId)
        .maybeSingle();
      if (data) setLastSyncDate(data.updated_at);
    } catch (e) {}
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      setUser(u);
      if (u) fetchLastSync(u.id);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const u = session?.user ?? null;
      setUser(u);
      if (u) fetchLastSync(u.id);
      else setLastSyncDate(null);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleBackup = () => {
    const dataStr = JSON.stringify({ history, customSongs, learningList }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_igreja_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && Array.isArray(json.history)) {
          if (window.confirm("Isso substituirá seus dados atuais. Continuar?")) {
            onRestore(json.history, json.customSongs || [], json.learningList || []);
          }
        }
      } catch (err) { alert("Arquivo inválido."); }
    };
    reader.readAsText(file);
  };

  const handleRestoreFromCloud = async () => {
    if (!user) return;
    if (!window.confirm("Substituir dados locais pela versão da nuvem?")) return;

    setIsSyncing(true);
    try {
      const { data } = await supabase.from('user_data').select('json_data').eq('user_id', user.id).maybeSingle();
      if (data?.json_data) {
        onRestore(data.json_data.history || [], data.json_data.customSongs || [], data.json_data.learningList || []);
        alert("Restaurado com sucesso!");
      } else {
        alert("Nenhum dado encontrado na nuvem para este usuário.");
      }
    } catch (e: any) { alert("Erro ao baixar dados."); }
    finally { setIsSyncing(true); setTimeout(() => setIsSyncing(false), 1000); }
  };

  const handleUploadToCloud = async () => {
    if (!user) return;
    if (!window.confirm("Deseja enviar seus dados locais atuais para a nuvem? Isso sobrescreverá o backup online anterior.")) return;

    setIsSyncing(true);
    try {
      const { error } = await supabase.from('user_data').upsert({
        user_id: user.id,
        json_data: { history, customSongs, learningList },
        updated_at: new Date().toISOString()
      }, { onConflict: 'user_id' });

      if (error) throw error;

      await fetchLastSync(user.id);
      alert("Dados enviados para a nuvem com sucesso!");
    } catch (e: any) {
      alert("Erro ao enviar dados: " + e.message);
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800 flex items-center gap-3">
          <span className="material-icons text-indigo-600">settings</span>
          Gestão de Dados
        </h2>
      </div>

      <div className="bg-[#1a1c3d] rounded-[2.5rem] p-8 md:p-12 shadow-2xl border border-white/5 relative overflow-hidden">
        <div className="absolute -right-10 -bottom-10 opacity-5">
           <span className="material-icons text-[15rem]">storage</span>
        </div>

        <div className="relative z-10">
          {!user ? (
            <div className="flex flex-col items-center text-center space-y-6">
              <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center text-white/20">
                <span className="material-icons text-3xl">cloud_off</span>
              </div>
              <div className="max-w-xs">
                <h3 className="text-white font-black text-lg uppercase tracking-tight">Sincronização Desativada</h3>
                <p className="text-white/40 text-[9px] font-bold uppercase tracking-widest mt-2 leading-relaxed">
                  Conecte-se através do menu lateral para habilitar o backup automático.
                </p>
              </div>
            </div>
          ) : (
            <div className="flex flex-col space-y-8">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
                <div className="flex items-center gap-6">
                  <div className="w-16 h-16 rounded-3xl bg-emerald-500 text-white flex items-center justify-center shadow-xl animate-scaleUp">
                    <span className="material-icons text-3xl">verified_user</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] mb-1">Backup na Nuvem</span>
                    <h3 className="text-white font-black text-lg tracking-tight truncate max-w-[200px]">
                      {user.email}
                    </h3>
                    <p className="text-white/40 text-[10px] font-medium uppercase mt-1">
                      {lastSyncDate ? `Último envio: ${new Date(lastSyncDate).toLocaleString('pt-BR')}` : 'Aguardando sincronização'}
                    </p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-4 border-t border-white/5">
                <button 
                  disabled={isSyncing}
                  onClick={handleUploadToCloud}
                  className="bg-indigo-500 text-white hover:bg-indigo-600 px-6 py-5 rounded-3xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  <span className={`material-icons ${isSyncing ? 'animate-spin' : ''}`}>
                    {isSyncing ? 'sync' : 'cloud_upload'}
                  </span>
                  Forçar Envio
                </button>

                <button 
                  disabled={isSyncing}
                  onClick={handleRestoreFromCloud}
                  className="bg-white/10 text-white hover:bg-white/20 px-6 py-5 rounded-3xl font-black text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  <span className={`material-icons ${isSyncing ? 'animate-spin' : ''}`}>
                    {isSyncing ? 'sync' : 'cloud_download'}
                  </span>
                  Baixar Nuvem
                </button>
              </div>

              <p className="text-center text-white/20 text-[9px] font-black uppercase tracking-[0.3em]">
                O auto-sync salva alterações automaticamente a cada 2 segundos
              </p>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center group">
          <div className="w-16 h-16 bg-indigo-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-indigo-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-3xl">download</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase">Exportar Arquivo</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed">Baixar backup manual para segurança local.</p>
          <button onClick={handleBackup} className="w-full py-5 bg-indigo-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase">GERAR JSON</button>
        </div>

        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center group">
          <div className="w-16 h-16 bg-emerald-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-emerald-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-3xl">upload</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase">Importar Arquivo</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed">Restaurar dados de um arquivo baixado.</p>
          <button onClick={() => fileInputRef.current?.click()} className="w-full py-5 bg-emerald-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase">SELECIONAR</button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>
    </div>
  );
};

export default BackupRestore;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft, PraiseLearningItem } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import PraiseLearningList from './components/PraiseLearningList';
import AuthForm from './components/AuthForm';
import { initDB, saveData, loadData } from './db';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'learning' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [learningList, setLearningList] = useState<PraiseLearningItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'local'>('local');

  const [isReadyForCloudSync, setIsReadyForCloudSync] = useState(false);
  const syncTimeoutRef = useRef<number | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  // 1. Inicialização do Sistema
  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const localData = await loadData();

        if (localData) {
          if (localData.history) setHistory(localData.history);
          if (localData.customSongs) setCustomSongs(localData.customSongs);
          if (localData.learningList) setLearningList(localData.learningList);
          if (localData.draft) setDraft({ ...localData.draft, date: getTodayDate() });
        }

        const { data: { session } } = await supabase.auth.getSession();
        const currentUser = session?.user ?? null;
        setUser(currentUser);

        if (currentUser) {
          const { data: cloudData } = await supabase
            .from('user_data')
            .select('json_data')
            .eq('user_id', currentUser.id)
            .maybeSingle();

          if (cloudData?.json_data) {
            const cloud = cloudData.json_data;
            if (localData?.history?.length === 0 && cloud.history?.length > 0) {
              setHistory(cloud.history);
              setCustomSongs(cloud.customSongs || []);
              setLearningList(cloud.learningList || []);
            }
          }
        }
      } catch (e) {
        console.error("Erro no setup inicial:", e);
      } finally {
        setIsLoading(false);
        setIsReadyForCloudSync(true);
      }
    };
    setup();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      subscription.unsubscribe();
    };
  }, []);

  // 2. Persistência Local
  useEffect(() => {
    if (isLoading) return;
    saveData({ history, customSongs, draft, learningList });
  }, [history, customSongs, draft, learningList, isLoading]);

  // 3. Auto-Sync Cloud
  useEffect(() => {
    if (!isReadyForCloudSync || !user || isOffline) return;

    setSyncStatus('syncing');
    if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);

    syncTimeoutRef.current = window.setTimeout(async () => {
      try {
        const { error } = await supabase.from('user_data').upsert({ 
          user_id: user.id, 
          json_data: { history, customSongs, learningList },
          updated_at: new Date().toISOString()
        }, { onConflict: 'user_id' });

        if (error) throw error;
        setSyncStatus('synced');
      } catch (e) {
        console.error("Falha no Auto-Sync Cloud:", e);
        setSyncStatus('local');
      }
    }, 2000);

    return () => {
      if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
    };
  }, [history, customSongs, learningList, user, isOffline, isReadyForCloudSync]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => (
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center p-2.5">
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
      </div>
      <div className="flex flex-col">
        <div className="flex items-center gap-2">
           <span className={`material-icons text-[14px] ${syncStatus === 'synced' ? 'text-emerald-400' : syncStatus === 'syncing' ? 'text-amber-400 animate-spin' : 'text-white/20'}`}>
             {syncStatus === 'synced' ? 'cloud_done' : syncStatus === 'syncing' ? 'sync' : 'cloud_off'}
           </span>
           <span className="text-white/60 font-black text-[10px] tracking-[0.2em] uppercase">
             {syncStatus === 'synced' ? 'Nuvem OK' : syncStatus === 'syncing' ? 'Salvando...' : 'Local'}
           </span>
        </div>
        <h1 className="text-white font-black text-xl tracking-tighter leading-tight uppercase whitespace-nowrap">Santo Antônio II</h1>
        <div className="mt-1 bg-white/10 self-start px-3 py-1 rounded-full flex items-center gap-2">
           <span className="material-icons text-amber-400 text-xs">analytics</span>
           <span className="text-white font-black text-[10px] uppercase">{history.length} Cultos</span>
        </div>
      </div>
    </div>
  );

  const UserProfile = () => {
    if (!user) return (
      <button 
        onClick={() => { setIsAuthModalOpen(true); setIsMobileMenuOpen(false); }}
        className="mx-6 mb-8 p-6 bg-indigo-500 hover:bg-indigo-600 rounded-[2rem] flex items-center gap-4 text-white shadow-xl transition-all active:scale-95 group"
      >
        <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center group-hover:bg-white/30 transition-colors">
          <span className="material-icons text-xl">cloud_upload</span>
        </div>
        <div className="text-left">
          <span className="block text-[10px] font-black uppercase tracking-widest opacity-60 leading-none mb-1">Backup Cloud</span>
          <span className="block font-black text-xs uppercase">Conectar Nuvem</span>
        </div>
      </button>
    );
    return (
      <div className="mx-6 mb-8 p-5 bg-white/5 border border-white/5 rounded-[2rem] flex items-center justify-between group">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-indigo-50/10 rounded-xl flex items-center justify-center border border-white/10">
            {user.user_metadata?.avatar_url ? (
              <img src={user.user_metadata.avatar_url} alt="Avatar" className="w-full h-full object-cover rounded-lg" />
            ) : (
              <span className="material-icons text-indigo-300 text-xl">person</span>
            )}
          </div>
          <div className="flex flex-col min-w-0">
            <span className="text-white font-black text-[10px] uppercase truncate max-w-[120px]">{user.user_metadata?.full_name || user.email}</span>
            <span className="text-emerald-400 font-bold text-[8px] uppercase tracking-widest flex items-center gap-1">
              <span className="w-1 h-1 bg-emerald-400 rounded-full animate-pulse"></span>
              Sincronizado
            </span>
          </div>
        </div>
        <button 
          onClick={() => supabase.auth.signOut()}
          className="w-8 h-8 flex items-center justify-center text-white/20 hover:text-rose-400 transition-colors"
          title="Sair"
        >
          <span className="material-icons text-lg">logout</span>
        </button>
      </div>
    );
  };

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex flex-col items-center justify-center text-white p-10"><img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-20 h-20 animate-bounce mb-6" /><p className="font-black tracking-widest text-sm animate-pulse">CARREGANDO SISTEMA...</p></div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      <aside className="hidden md:flex w-96 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-12 border-b border-white/5">
          <AppBrand />
        </div>
        <nav className="flex-1 py-10 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`w-full flex items-center gap-6 px-12 py-6 transition-all duration-300 ${activeTab === item.id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="text-sm uppercase font-black tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <UserProfile />
      </aside>

      <header className="md:hidden bg-[#1a1c3d] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl rounded-b-[2rem]">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="p-4 bg-white/10 rounded-2xl active:scale-90 transition-transform">
          <span className="material-icons text-3xl">menu</span>
        </button>
      </header>

      {/* Modal de Autenticação Global */}
      {isAuthModalOpen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-xl animate-fadeIn" onClick={() => setIsAuthModalOpen(false)} />
          <div className="relative bg-[#1a1c3d] rounded-[3.5rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp border border-white/10 flex flex-col items-center">
            <div className="w-20 h-20 bg-indigo-500 rounded-3xl flex items-center justify-center mb-8 shadow-2xl">
              <span className="material-icons text-white text-4xl">cloud_sync</span>
            </div>
            <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight text-center">Conectar Nuvem</h3>
            <p className="text-white/40 font-bold text-[10px] uppercase tracking-[0.2em] mb-10 text-center leading-relaxed">
              Sincronize seus dados em tempo real entre todos os seus dispositivos.
            </p>

            <AuthForm onSuccess={() => setIsAuthModalOpen(false)} />

            <button 
              onClick={() => setIsAuthModalOpen(false)}
              className="mt-8 text-white/30 font-black uppercase text-[10px] tracking-widest hover:text-white transition-colors"
            >
              Voltar
            </button>
          </div>
        </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-lg" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1a1c3d] shadow-2xl flex flex-col animate-fadeIn border-l border-white/5">
            <div className="p-10 flex justify-between items-center border-b border-white/5">
              <span className="text-white/40 font-black text-xs tracking-widest uppercase">Menu Principal</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center text-white/40"><span className="material-icons">close</span></button>
            </div>
            <nav className="flex-1 py-6 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={`w-full flex items-center gap-8 px-10 py-7 border-b border-white/5 ${activeTab === item.id ? 'text-amber-400 bg-white/5 font-black' : 'text-white/60'}`}
                >
                  <span className="material-icons text-3xl">{item.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </nav>
            <UserProfile />
          </div>
        </div>
      )}

      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-[92px] md:top-0 z-[190] shadow-lg">Operando Offline.</div>}

        <div className="px-4 pt-14 pb-20 md:p-16 animate-fadeIn max-w-6xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'learning' && <PraiseLearningList fullSongList={fullSongList} learningList={learningList} setLearningList={setLearningList} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={INITIAL_PRAISE_LIST} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} learningList={learningList} onRestore={(h, c, l) => { setHistory(h); setCustomSongs(c); setLearningList(l || []); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { ServiceRecord, PraiseLearningItem } from '../types';
import { supabase } from '../supabase';

interface Props {
  history: ServiceRecord[];
  customSongs: string[];
  learningList: PraiseLearningItem[];
  onRestore: (history: ServiceRecord[], customSongs: string[], learningList: PraiseLearningItem[]) => void;
}

const BackupRestore: React.FC<Props> = ({ history, customSongs, learningList, onRestore }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncDate, setLastSyncDate] = useState<string | null>(null);

  const fetchLastSync = async (userId: string) => {
    try {
      const { data } = await supabase
        .from('user_data')
        .select('updated_at')
        .eq('user_id', userId)
        .maybeSingle();
      if (data) setLastSyncDate(data.updated_at);
    } catch (e) {}
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      setUser(u);
      if (u) fetchLastSync(u.id);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const u = session?.user ?? null;
      setUser(u);
      if (u) fetchLastSync(u.id);
      else setLastSyncDate(null);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleBackup = () => {
    const dataStr = JSON.stringify({ history, customSongs, learningList }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_igreja_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && Array.isArray(json.history)) {
          if (window.confirm("Isso substituirá seus dados atuais. Continuar?")) {
            onRestore(json.history, json.customSongs || [], json.learningList || []);
          }
        }
      } catch (err) { alert("Arquivo inválido."); }
    };
    reader.readAsText(file);
  };

  const handleRestoreFromCloud = async () => {
    if (!user) return;
    if (!window.confirm("Substituir dados locais pela versão da nuvem?")) return;

    setIsSyncing(true);
    try {
      const { data } = await supabase.from('user_data').select('json_data').eq('user_id', user.id).maybeSingle();
      if (data?.json_data) {
        onRestore(data.json_data.history || [], data.json_data.customSongs || [], data.json_data.learningList || []);
        alert("Restaurado com sucesso!");
      } else {
        alert("Nenhum dado encontrado na nuvem.");
      }
    } catch (e: any) { alert("Erro ao baixar dados."); }
    finally { setIsSyncing(false); }
  };

  const handleUploadToCloud = async () => {
    if (!user) return;
    if (!window.confirm("Sobrescrever backup online com os dados locais atuais?")) return;

    setIsSyncing(true);
    try {
      const { error } = await supabase.from('user_data').upsert({
        user_id: user.id,
        json_data: { history, customSongs, learningList },
        updated_at: new Date().toISOString()
      }, { onConflict: 'user_id' });

      if (error) throw error;

      await fetchLastSync(user.id);
      alert("Enviado com sucesso!");
    } catch (e: any) {
      alert("Erro ao enviar dados: " + e.message);
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800 flex items-center gap-3">
          <span className="material-icons text-indigo-600">settings</span>
          Gestão de Sistema
        </h2>
      </div>

      <div className="bg-[#1a1c3d] rounded-[2.5rem] p-8 md:p-12 shadow-2xl border border-white/5 relative overflow-hidden">
        <div className="absolute -right-10 -bottom-10 opacity-5">
           <span className="material-icons text-[15rem]">cloud_sync</span>
        </div>

        <div className="relative z-10">
          {!user ? (
            <div className="flex flex-col items-center text-center py-4 space-y-6">
              <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center text-white/20">
                <span className="material-icons text-3xl">cloud_off</span>
              </div>
              <div className="max-w-xs">
                <h3 className="text-white font-black text-lg uppercase tracking-tight">Sincronização Desativada</h3>
                <p className="text-white/40 text-[10px] font-bold uppercase tracking-widest mt-2 leading-relaxed">
                  Conecte-se através do botão na barra lateral para ativar o backup automático.
                </p>
              </div>
            </div>
          ) : (
            <div className="flex flex-col space-y-8">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
                <div className="flex items-center gap-6">
                  <div className="w-16 h-16 rounded-3xl bg-emerald-500 text-white flex items-center justify-center shadow-xl animate-scaleUp">
                    <span className="material-icons text-3xl">cloud_done</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] mb-1">Nuvem Conectada</span>
                    <h3 className="text-white font-black text-lg tracking-tight truncate max-w-[220px]">
                      {user.email}
                    </h3>
                    <p className="text-white/40 text-[10px] font-medium uppercase mt-1">
                      {lastSyncDate ? `Último envio: ${new Date(lastSyncDate).toLocaleString('pt-BR')}` : 'Aguardando sincronização'}
                    </p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-4 border-t border-white/5">
                <button 
                  disabled={isSyncing}
                  onClick={handleUploadToCloud}
                  className="bg-indigo-500 text-white hover:bg-indigo-600 px-6 py-5 rounded-3xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  <span className={`material-icons ${isSyncing ? 'animate-spin' : ''}`}>
                    {isSyncing ? 'sync' : 'cloud_upload'}
                  </span>
                  Forçar Envio
                </button>

                <button 
                  disabled={isSyncing}
                  onClick={handleRestoreFromCloud}
                  className="bg-white/10 text-white hover:bg-white/20 px-6 py-5 rounded-3xl font-black text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
                >
                  <span className={`material-icons ${isSyncing ? 'animate-spin' : ''}`}>
                    {isSyncing ? 'sync' : 'cloud_download'}
                  </span>
                  Baixar Nuvem
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center group">
          <div className="w-16 h-16 bg-indigo-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-indigo-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-3xl">download</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase">Exportar Arquivo</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed">Backup manual offline (JSON).</p>
          <button onClick={handleBackup} className="w-full py-5 bg-indigo-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase">BAIXAR ARQUIVO</button>
        </div>

        <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center text-center group">
          <div className="w-16 h-16 bg-emerald-50 rounded-[1.5rem] flex items-center justify-center mb-6 text-emerald-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-3xl">upload</span>
          </div>
          <h4 className="text-lg font-black text-[#1a1c3d] mb-2 uppercase">Importar Arquivo</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-8 tracking-widest leading-relaxed">Restaurar de backup JSON local.</p>
          <button onClick={() => fileInputRef.current?.click()} className="w-full py-5 bg-emerald-500 text-white font-black rounded-[2rem] shadow-lg active:scale-95 transition-all text-[11px] tracking-widest uppercase">ABRIR BACKUP</button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>
    </div>
  );
};

export default BackupRestore;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft, PraiseLearningItem } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import PraiseLearningList from './components/PraiseLearningList';
import AuthForm from './components/AuthForm';
import { initDB, saveData, loadData } from './db';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'learning' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [learningList, setLearningList] = useState<PraiseLearningItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'local'>('local');

  const [isReadyForCloudSync, setIsReadyForCloudSync] = useState(false);
  const syncTimeoutRef = useRef<number | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  // 1. Inicialização do Sistema
  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const localData = await loadData();

        if (localData) {
          if (localData.history) setHistory(localData.history);
          if (localData.customSongs) setCustomSongs(localData.customSongs);
          if (localData.learningList) setLearningList(localData.learningList);
          if (localData.draft) setDraft({ ...localData.draft, date: getTodayDate() });
        }

        const { data: { session } } = await supabase.auth.getSession();
        const currentUser = session?.user ?? null;
        setUser(currentUser);

        if (currentUser) {
          const { data: cloudData } = await supabase
            .from('user_data')
            .select('json_data')
            .eq('user_id', currentUser.id)
            .maybeSingle();

          if (cloudData?.json_data) {
            const cloud = cloudData.json_data;
            if (localData?.history?.length === 0 && cloud.history?.length > 0) {
              setHistory(cloud.history);
              setCustomSongs(cloud.customSongs || []);
              setLearningList(cloud.learningList || []);
            }
          }
        }
      } catch (e) {
        console.error("Erro no setup inicial:", e);
      } finally {
        setIsLoading(false);
        setIsReadyForCloudSync(true);
      }
    };
    setup();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      subscription.unsubscribe();
    };
  }, []);

  // 2. Persistência Local
  useEffect(() => {
    if (isLoading) return;
    saveData({ history, customSongs, draft, learningList });
  }, [history, customSongs, draft, learningList, isLoading]);

  // 3. Auto-Sync Cloud
  useEffect(() => {
    if (!isReadyForCloudSync || !user || isOffline) return;

    setSyncStatus('syncing');
    if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);

    syncTimeoutRef.current = window.setTimeout(async () => {
      try {
        const { error } = await supabase.from('user_data').upsert({ 
          user_id: user.id, 
          json_data: { history, customSongs, learningList },
          updated_at: new Date().toISOString()
        }, { onConflict: 'user_id' });

        if (error) throw error;
        setSyncStatus('synced');
      } catch (e) {
        console.error("Falha no Auto-Sync Cloud:", e);
        setSyncStatus('local');
      }
    }, 2000);

    return () => {
      if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
    };
  }, [history, customSongs, learningList, user, isOffline, isReadyForCloudSync]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const CloudStatusButton = () => (
